### Iteration 2: Optimizing with Shared Memory
I'll now optimize the kernel by adding shared memory to reduce global memory accesses. This technique loads blocks of matrices into faster shared memory, reducing memory bandwidth constraints.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16

__global__ void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    float sum = 0.0f;

    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load tile from A
        int tiled_row = threadIdx.y;
        int tiled_col = t * TILE_SIZE + threadIdx.x;
        if (row < M && tiled_col < K) {
            As[tiled_row][threadIdx.x] = A[row * K + tiled_col];
        } else {
            As[tiled_row][threadIdx.x] = 0.0f;
        }

        // Load tile from B
        tiled_row = t * TILE_SIZE + threadIdx.y;
        tiled_col = threadIdx.x;
        if (tiled_row < K && col < N) {
            Bs[threadIdx.y][tiled_col] = B[tiled_row * N + col];
        } else {
            Bs[threadIdx.y][tiled_col] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += As[tiled_row][k] * Bs[k][tiled_col];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_forward_cuda(
    torch::Tensor A,
    torch::Tensor B
) {
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions mismatch");

    int M = A.size(0);
    int N = B.size(1);
    int K = A.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((N + block.x - 1) / block.x, (M + block.y - 1) / block.y);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K
    );

    return C;
}
"""

